    expect(sympyStr([at(v1, 0), at(v1, 1)], 't')).toBe('(-2*a*x*y + a*(x + y)**2 - 3*x*y*(x + y) + (x + y)**3, y**3*(b - 1) + y**2*(1 - a))');
